              {price}
            </Text>
          </View>
          {popular ? (
            <Badge color="primary" variant="faded" size="small" rounded>
              Popular
            </Badge>
          ) : null}
        </View>

        <ul style={{ margin: 0, paddingLeft: 16, listStyle: 'disc' }}>
          {features.map((feature) => (
            <li key={feature}>
              <Text variant="body-2" color="neutral">
                {feature}
