        <Button
          color="primary"
          onClick={onSelect}
          attributes={{ 'data-testid': 'plan-cta' }}
          fullWidth
        >
          {ctaLabel}
        </Button>

        {footer ? (
          <Text variant="caption-1" color="neutral-faded">
            {footer}
          </Text>
        ) : null}
      </View>
    </View>
  );
}

