export type ButtonProps = {
  label: string;
  onClick?: () => void;
  disabled?: boolean;
  variant?: 'primary' | 'secondary';
};

export default function Button({
  label,
  onClick,
  disabled = false,
  variant = 'primary',
}: ButtonProps) {
  const background = variant === 'primary' ? '#1d4ed8' : '#e5e7eb';
  const color = variant === 'primary' ? '#ffffff' : '#111827';

  return (
    <button
      type="button"
      disabled={disabled}
      onClick={onClick}
      style={{
        backgroundColor: background,
        border: 'none',
        borderRadius: 6,
        color,
        cursor: disabled ? 'not-allowed' : 'pointer',
        fontSize: 14,
        fontWeight: 600,
        opacity: disabled ? 0.6 : 1,
        padding: '8px 16px',
      }}
    >
      {label}
    </button>
  );
}

export type TagProps = {
  label: string;
  tone?: 'neutral' | 'positive' | 'notice';
};

const TONE_COLORS = {
  neutral: { background: '#f3f4f6', color: '#374151' },
  positive: { background: '#dcfce7', color: '#166534' },
  notice: { background: '#fef9c3', color: '#854d0e' },
} as const;

export default function Tag({ label, tone = 'neutral' }: TagProps) {
  const colors = TONE_COLORS[tone];

  return (
    <span
      style={{
        backgroundColor: colors.background,
        borderRadius: 4,
        color: colors.color,
        display: 'inline-block',
        fontSize: 12,
        fontWeight: 600,
        padding: '2px 8px',
        textTransform: 'uppercase',
      }}
    >
      {label}
    </span>
  );
}

